function [u,balancing] = furuta_sac_rev11f_step(x,active)
%#codegen
% Generated by sp_write_rl_wrapper around furuta_sac_rev11f_policy
persistent on
if isempty(on), on=false; end
x=double(x(:)); u=0; balancing=false;
x(2)=x(2)-0.048345620280242932;   % pendulum zero trim [rad]
if ~active, on=false; return; end
th=atan2(sin(x(2)),cos(x(2)));
o=[cos(x(2)); sin(x(2)); x(1); x(3); x(4)];
u=furuta_sac_rev11f_policy(o);
balancing=abs(th)<20*pi/180;
u=max(-1,min(1,u(1)));
end
